/**
 * 内置示范课 16:9 无字水彩 / 几何插画库（0 秒加载、免 API Key、离线直写 .pptx）
 * 覆盖《荷塘月色》《桂花雨》《草船借箭》《圆的面积》《长方体的认识》五大公开课示范课。
 */
import type { StudentSlide } from '../lib/slides'

export interface BuiltinArtPack {
  id: string
  match: RegExp
  cover: string
  scene?: string
}

const HETANGCOVER = "data:image/jpeg;base64,"
const HETANGSCENE = "data:image/jpeg;base64,"
const GUIHUACOVER = "data:image/jpeg;base64,"
const CAOCHUANCOVER = "data:image/jpeg;base64,"
const YUANMIANJICOVER = "data:image/jpeg;base64,"
const CHANGFANGTICOVER = "data:image/jpeg;base64,"

export const BUILTIN_ART_PACKS: readonly BuiltinArtPack[] = [
  { id: "hetang", match: /荷塘月色|荷塘/, cover: HETANGCOVER, scene: HETANGSCENE },
  { id: "guihua", match: /桂花雨|桂花/, cover: GUIHUACOVER, scene: GUIHUACOVER },
  { id: "caochuan", match: /草船借箭|草船/, cover: CAOCHUANCOVER, scene: CAOCHUANCOVER },
  { id: "yuanmianji", match: /圆的面积|圆面积/, cover: YUANMIANJICOVER, scene: YUANMIANJICOVER },
  { id: "changfangti", match: /长方体|正方体/, cover: CHANGFANGTICOVER, scene: CHANGFANGTICOVER },
]

/** 按课题匹配内置 16:9 艺术插画包；未命中返回 null */
export function builtinArtFor(topic: string): BuiltinArtPack | null {
  const t = String(topic ?? "").trim()
  if (!t) return null
  return BUILTIN_ART_PACKS.find((p) => p.match.test(t)) ?? null
}

/** 为学生版幻灯片挂载预置 16:9 艺术插画（保留已有插画，不覆盖用户替换图） */
export function attachBuiltinArt(slides: readonly StudentSlide[], topic: string): StudentSlide[] {
  const pack = builtinArtFor(topic)
  if (!pack || !Array.isArray(slides) || slides.length === 0) return slides as StudentSlide[]
  let sceneApplied = 0
  return slides.map((s) => {
    if (s.illustration) return s
    if (s.kind === "cover") {
      return { ...s, illustration: pack.cover, coverArch: s.coverArch ?? "left", coverScrim: s.coverScrim ?? 0.72 }
    }
    if (pack.scene && sceneApplied < 2 && (s.kind === "hook" || s.kind === "close-read")) {
      sceneApplied += 1
      return { ...s, illustration: pack.scene, artSide: s.artSide ?? "right" }
    }
    return s
  })
}
